 const svg={captured:new Set(),addEventListener(k,f){(svgListeners[k]??=[]).push(f)},setPointerCapture(i){this.captured.add(i)},releasePointerCapture(i){this.captured.delete(i)},hasPointerCapture(i){return this.captured.has(i)},createSVGPoint(){return{x:0,y:0,matrixTransform(){return{x:this.x/10,y:this.y/10}}}},getScreenCTM(){return{inverse(){return{}}}}};
 const c={console,Math,document:{hidden:false,getElementById:()=>svg,addEventListener(k,f){(docListeners[k]??=[]).push(f)}},addEventListener(k,f){(listeners[k]??=[]).push(f)},MuseumObservation:{mountLesson(options){mounted=options;}},MechanicalAudio:{enabled:true,getContext:()=>ctx,getOutput:()=>output,pulse(){},onChange(){}}};c.window=c;vm.createContext(c);vm.runInContext(read('dist/core.js'),c);vm.runInContext(baseline?baselines[id]:sources[id],c);const cfg=c.SCENES[id](),s=cfg.state,ui={animate(f,options={}){callbacks.set(f,options)},invalidate(){},flash(t){flashes.push(t)}};cfg.setup(ui);
