const TAU=Math.PI*2,CONTACT=Math.atan2(-5.25,5.5),HALF=.11,wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));
function crossings(from,to){const dir=Math.sign(to-from),events=[];for(let i=0;i<12;i++)for(let j=0;j<3;j++){const base=CONTACT+dir*HALF-j*TAU/3-i*.79;if(dir>0){for(let k=Math.floor((from-base)/TAU)+1;k<=Math.floor((to-base)/TAU);k++)events.push({at:base+k*TAU,tooth:i});}else{for(let k=Math.ceil((from-base)/TAU)-1;k>=Math.ceil((to-base)/TAU);k--)events.push({at:base+k*TAU,tooth:i});}}return events.sort((a,b)=>(a.at-b.at)*dir);}
function checkMusic(f){const r=f.read(),all=Array.from({length:12},(_,i)=>({tooth:i,phase:[0,1,2].map(j=>wrap(f.s.angle+j*TAU/3+i*.79-CONTACT)).sort((a,b)=>Math.abs(a)-Math.abs(b))[0]})).sort((a,b)=>Math.abs(a.phase)-Math.abs(b.phase));assert.equal(r.tooth,all[0].tooth);near(r.pinPhase,all[0].phase);assert.equal(r.contact,Math.abs(r.pinPhase)<HALF);near(r.deflection,r.contact?.35*Math.cos(r.pinPhase/HALF*Math.PI/2):0);assert.equal(r.notes,f.s.notes);assert.equal(r.lastTooth,f.s.lastTooth);assert.equal(r.index,r.contact?(r.pinPhase*r.direction<0?1:2):0);assert.equal(r.busy,f.s.crankHeld);const ob=f.cfg.observation.read(f.s);if(r.contact){assert(ob.active.includes('music-tooth-'+r.tooth),'observer highlights card tooth');assert(ob.text.includes('第 '+(r.tooth+1)+' 根'),'observer text names card tooth');}return r;}
function checkTable(f){const r=f.read();assert.equal(r.selectedRpm,f.s.rpm);assert.equal(r.actualRpm,f.s.platterRpm);assert.equal(r.contact,f.s.cue==='down'&&f.s.lift<.01&&f.s.arm>.99);near(r.needleGap,27+f.s.lift*4-2.7-24.3);assert.equal(r.elapsed,f.s.elapsed);assert.equal(r.choices.filter(x=>x.disabled).length,1);assert.equal(r.choices.find(x=>x.disabled).id,'rpm-'+f.s.rpm);if(f.s.cue==='parking'||f.s.cue==='returning')assert.equal(r.index,4);return r;}
function save(f,label){const r=f.id==='musicbox'?checkMusic(f):checkTable(f);snapshots.push({id:f.id,label,state:clone(f.s),lesson:clone(r)});}
