test('Physical controller, audio, artwork, pin mapping and safe-transfer source stay byte-identical to eb9c742',()=>{for(const id of Object.keys(sources)){const end=id==='musicbox'?'  const cfg=':"  return {title:'唱片机'",physical=s=>s.slice(s.indexOf('  // Keep short release'),s.indexOf(end));assert.equal(hash(physical(sources[id])),hash(physical(baselines[id])),id+' physical/audio source');assert(!/setTimeout|setInterval|requestAnimationFrame/.test(sources[id]),id+' creates no scene timer');}});
test('Both cards use live non-linear mount, start disabled, and opt-in/out cannot mutate physical state',()=>{for(const id of Object.keys(sources)){const f=rig(id),before=clone(f.s);assert.equal(f.cfg.observation.title,'看原理');assert.equal(f.cfg.observation.slow,true);assert.equal(f.mounted.linear,false);assert.equal(f.mounted.onPause,undefined);assert.equal(f.read().enabled,false);f.next();f.choice(id==='turntable'?'rpm-45':'open-lid');assert.deepEqual(clone(f.s),before);f.toggle();assert.equal(f.read().enabled,true);f.toggle(false);assert.deepEqual(clone(f.s),before);assert.equal(f.callbacks.size,0);}});
test('Music: stationary initial contact is not a pluck; nearest pin phase/deflection match geometry for 1,440 orientations',()=>{const f=rig('musicbox');save(f,'stationary-contact');assert(f.read().contact);assert.match(f.read().title,/停在接触处/);assert.equal(f.s.notes,0);for(const direction of [-1,1])for(let i=0;i<720;i++){f.s.angle=-TAU+i*TAU/360;f.s.direction=direction;checkMusic(f);}assert.equal(f.s.notes,0);});
test('Music: overlapping contacts exist; both card and observer select the same physical tooth, including held-without-motion',()=>{const f=rig('musicbox');let overlaps=0,different=0;for(let i=0;i<720;i++){f.s.angle=i*TAU/720;const touching=[];for(let tooth=0;tooth<12;tooth++)if([0,1,2].some(j=>Math.abs(wrap(f.s.angle+j*TAU/3+tooth*.79-CONTACT))<HALF))touching.push(tooth);const r=checkMusic(f);if(touching.length>1){overlaps++;if(r.tooth!==touching[0])different++;}}assert(overlaps>0&&different>0,'exercise former first-vs-nearest mismatch');f.button('重新开始');f.render();const [x,y]=f.point(0);f.event('pointerdown',{key:'crank',clientX:x,clientY:y});assert.match(f.read().title,/停在接触处/);assert.equal(f.s.notes,0);f.event('pointercancel');});
test('Music: direct forward/reverse circular dragging counts exact release edges and keeps card readouts physical',()=>{const f=rig('musicbox');f.toggle();for(const delta of [.12,1.3,1.2,-1.4,-1.1,.9]){const before=f.s.angle,n=f.s.notes;f.drag(delta);near(f.s.angle,before+delta);const expected=crossings(before,before+delta);assert.equal(f.s.notes-n,expected.length);if(expected.length)assert.equal(f.s.lastTooth,expected.at(-1).tooth);const r=checkMusic(f),ob=f.cfg.observation.read(f.s);if(r.contact)assert(ob.active.includes('music-tooth-'+r.tooth),'card tooth and artwork highlight agree');const held=clone(f.s);f.next();assert.deepEqual(clone(f.s),held,'lesson does not fight a held crank');save(f,'drag-'+delta);f.event('pointercancel');f.tick(.1);}assert.equal(f.s.energy,0);});
test('Music: pluck belongs to tooth-specific pitch, no note before leaving its contact window',()=>{const f=rig('musicbox');f.toggle();f.next();const expected=crossings(0,.12);assert.equal(f.s.notes,expected.length);assert.equal(f.sounds.length,expected.length);for(let i=0;i<expected.length;i++)near(f.sounds[i].frequency.value,440*2**((72+expected[i].tooth-69)/12));const g=rig('musicbox');g.render();g.s.angle=CONTACT-.04;g.drag(.03);assert.equal(g.s.notes,0,'contact motion without exit has not released any tooth');assert(g.read().contact);g.event('pointercancel');});
test('Music: quarter-time coast preserves direct hand motion and release order, settles without idle callbacks',()=>{const fast=rig('musicbox'),slow=rig('musicbox');fast.toggle();slow.toggle();fast.next();slow.next();for(let k=0;k<100;k++){fast.frame(.01);for(let j=0;j<4;j++)slow.frame(.01,.25);}assert(fast.s.energy===0&&slow.s.energy===0);assert(fast.s.notes>0&&slow.s.notes>0);assert.equal(fast.callbacks.size,0);assert.equal(slow.callbacks.size,0);const n=slow.s.notes,before=slow.s.angle;slow.drag(-.8);near(slow.s.angle,before-.8);assert(slow.s.notes>n);slow.event('pointercancel');save(slow,'reverse-after-slow-coast');});
test('Music: exit, repeated folds, reset and every pointer cancellation preserve baseline state and cancel late notes',()=>{for(const cancel of ['pointercancel','lostpointercapture','Escape','blur','hidden','pagehide','reset']){const f=rig('musicbox'),old=rig('musicbox',{baseline:true});f.toggle();f.drag(1.1);old.drag(1.1);f.toggle(false);f.toggle();assert.deepEqual(clone(f.s),clone(old.s));for(const h of [f,old]){if(cancel==='Escape'||cancel==='blur'||cancel==='pagehide')for(const fn of h.listeners[cancel==='Escape'?'keydown':cancel]||[])fn(cancel==='Escape'?{key:'Escape'}:{});else if(cancel==='hidden'){h.c.document.hidden=true;for(const fn of h.docListeners.visibilitychange||[])fn();}else if(cancel==='reset')h.button('重新开始');else h.event(cancel);}const n=f.s.notes;for(let i=0;i<150;i++)pairFrame(f,old);assert.equal(f.s.notes,n);assert.equal(f.s.crankHeld,false);assert.equal(f.s.energy,0);assert(f.sounds.every(o=>o.ended));save(f,'cancel-'+cancel);}});
test('Music: conditional lid choice opens actual lid, cannot re-toggle from stale callback, exit retains coast',()=>{const f=rig('musicbox');f.act('lid');f.tick(1);f.toggle();const closed=clone(f.s);assert.equal(f.read().choices[0].id,'open-lid');f.choice('open-lid');assert.equal(f.s.lid,closed.lid);assert.equal(f.s.lidTarget,1);for(let i=0;i<20;i++)f.choice('open-lid');assert.equal(f.s.lidTarget,1);f.next();const at=f.s.angle;f.toggle(false);f.tick(.1);assert(f.s.angle>at);f.tick(2);assert.equal(f.s.lid,1);assert.equal(f.callbacks.size,0);save(f,'lid-open-after-exit');});
test('Turntable: primary follows real lift, transfer, settle, lower, contact, play and safe return, without fake completion',()=>{const f=rig('turntable'),seen=new Set(),capture=()=>{const phase=checkTable(f).phase;if(!seen.has(phase))save(f,'phase-'+phase);seen.add(phase);};f.toggle();save(f,'rest');f.next();for(let i=0;i<150;i++){capture();f.frame();}assert.equal(f.s.cue,'hover');assert.equal(f.s.arm,1);assert.equal(f.s.lift,1);save(f,'hover');f.next();for(let i=0;i<80;i++){capture();f.frame();}assert(f.read().contact);assert.equal(f.s.elapsed,0);save(f,'contact-still');f.next();f.tick(1);seen.add(f.read().phase);assert(f.s.elapsed>0);save(f,'playing');f.next();for(let i=0;i<200;i++){capture();f.frame();}assert.equal(f.s.cue,'rest');assert.equal(f.s.lift,1);assert.equal(f.s.arm,0);assert.equal(f.s.elapsed,0);assert.equal(f.callbacks.size,0);save(f,'manual-return-complete');for(const phase of ['transfer-lift','transfer-move','transfer-settle','lower','contact-still','playing','return-lift','return-move','return-settle'])assert(seen.has(phase),'observed '+phase);});
test('Turntable: 33/45 choice changes only target initially, then real speed/angle/progress and audio pitch',()=>{const f=rig('turntable');f.toggle();f.choice('rpm-45');assert.equal(f.s.rpm,45);assert.equal(f.s.platterRpm,0);const picked=clone(f.s);for(let k=0;k<30;k++)f.choice('rpm-45');assert.deepEqual(clone(f.s),picked);f.act('play');f.tick(1.2);assert.equal(f.s.platterRpm,45);assert.equal(f.s.elapsed,0);f.next();f.tick(1.2);f.next();f.tick(.8);const before=f.s.elapsed,angle=f.s.angle;f.tick(.1);near(f.s.elapsed-before,.1*45/33);near((f.s.angle-angle+TAU)%TAU,.1*45*Math.PI/30);save(f,'45-playing');f.choice('rpm-33');assert.equal(f.s.platterRpm,45,'selector must not teleport actual platter speed');f.tick(.1);assert(f.s.platterRpm<45&&f.s.platterRpm>33);f.tick(.3);assert.equal(f.s.platterRpm,33);checkTable(f);const g=rig('turntable');g.toggle();g.choice('rpm-45');g.next();g.tick(1.3);g.next();g.tick(.7);g.act('play');g.tick(1.3);const last=g.sounds.at(-1),seq=[48,55,60,64,62,55,59,62,53,60,65,69,55,62,67,71],n=Math.floor(g.s.elapsed*3);near(last.frequency.value,440*2**((seq[n%16]+12-69)/12)*45/33);});
test('Turntable: spinning alone and raised needle never progress or trigger notes; lifting preserves previous position',()=>{const f=rig('turntable');f.toggle();f.act('play');f.tick(2);assert.equal(f.read().phase,'spin-only');assert.equal(f.s.elapsed,0);assert.equal(f.sounds.length,0);f.next();f.tick(1.3);assert.equal(f.read().phase,'hover');assert.equal(f.sounds.length,0);f.next();f.tick(1);const elapsed=f.s.elapsed,count=f.sounds.length;f.act('cue');assert.equal(f.read().phase,'raise');f.tick(1);assert.equal(f.s.elapsed,elapsed);assert.equal(f.sounds.length,count);save(f,'lifted-preserving-progress');f.next();f.tick(1);assert(f.s.elapsed>elapsed);});
function distanceSegments(p1,q1,p2,q2){const sub=(a,b)=>a.map((v,k)=>v-b[k]),dot=(a,b)=>a.reduce((s,v,k)=>s+v*b[k],0),add=(p,d,t)=>p.map((v,k)=>v+d[k]*t),clamp=x=>Math.max(0,Math.min(1,x)),d1=sub(q1,p1),d2=sub(q2,p2),r=sub(p1,p2),a=dot(d1,d1),e=dot(d2,d2),b=dot(d1,d2),c=dot(d1,r),f=dot(d2,r),den=a*e-b*b;let s=den?clamp((b*f-c*e)/den):0,t=(b*s+f)/e;if(t<0){t=0;s=clamp(-c/a);}else if(t>1){t=1;s=clamp((b-c)/a);}return Math.hypot(...sub(add(p1,d1,s),add(p2,d2,t)));}
