test('Turntable: interrupted lower/transfer and early park retain full fork clearance in every actual sideways frame',()=>{for(const time of [.02,.12,.45,.73,1.2,1.5]){const f=rig('turntable');f.toggle();f.next();f.tick(time);if(!f.read().busy){f.next();f.tick(.16);}f.button('唱臂归位');for(let i=0;i<220;i++){const arm=f.s.arm;f.frame();if(arm!==f.s.arm){assert(f.s.lift>=1.65-.001);assert(clearance(f.s)>.5,'clear both actual fork tubes');}checkTable(f);}assert.equal(f.s.cue,'rest');assert.equal(f.s.arm,0);assert.equal(f.s.lift,1);save(f,'early-park-'+time);}});
