test('Shared helper: default folding, left primary placement, no pause control, non-linear route and exact node restoration',()=>{for(const id of Object.keys(sources)){const f=integrated(id),before=f.snapshot(),buttons=[...f.primary.children];assert.equal(f.panel.open,false);assert.equal(f.guide.open,false);assert.equal(f.read().enabled,false);assert.equal(f.pending,0);f.open();assert.equal(f.guide.parentElement,f.dock);assert.equal(f.primary.parentElement.className,'lesson-free-controls '+id+'-free-controls');assert.equal(f.primary.parentElement.open,false);assert.equal(f.snapshot(),before);assert.equal(f.hold.hidden,true);assert.match(f.guide.querySelector('.mechanism-lesson-title').textContent,/^当前 · /);for(const dot of f.guide.querySelectorAll('.mechanism-lesson-route span'))assert.equal(dot.dataset.done,'false');for(let i=0;i<12;i++){f.exit.click();assert.equal(f.primary.parentElement,f.dock);assert.equal(f.snapshot(),before);assert.deepEqual(f.primary.children,buttons);f.open();}f.exit.click();assert.equal(f.d.querySelectorAll('#btns').length,1);assert.equal(f.d.querySelectorAll('.mechanism-lesson').length,1);f.finish();assert.equal(f.pending,0);}});
test('Shared helper: native button keyboard activation callback uses current state, selected/stale choices and busy primary are inert',()=>{const f=integrated('turntable');f.open();for(const button of [f.go,f.hold,f.exit,...f.guide.querySelectorAll('.mechanism-lesson-choices button')]){assert.equal(button.tagName,'button');assert.equal(button.type,'button');assert.equal((button.events.keydown||[]).length,0,'no duplicate custom key activation');}const speed=f.choice('rpm-45');speed.focus();speed.click();assert.equal(f.s.rpm,45);assert.equal(speed.disabled,true);const before=f.snapshot();for(let i=0;i<30;i++)speed.onclick();assert.equal(f.snapshot(),before);assert(f.d.activeElement!==speed,'focus leaves newly disabled choice');f.go.focus();f.go.click();assert.equal(f.s.cue,'hover');assert.equal(f.go.getAttribute('aria-disabled'),'true');const moving=f.snapshot();for(let i=0;i<30;i++)f.go.click();assert.equal(f.snapshot(),moving);f.tick(1.3);assert.equal(f.s.lift,1);f.go.click();f.tick(.7);assert.equal(f.read().contact,true);f.go.click();f.tick(1);assert.equal(f.s.playing,true);const progress=f.s.elapsed;f.exit.click();const at=f.snapshot();speed.onclick();f.go.click();assert.equal(f.snapshot(),at);f.tick(.3);assert(f.s.elapsed>progress,'exit continues actual playback');f.button('重新开始');f.finish();});
test('Shared helper: parent close/reopen, 1/4 rate and hidden/page lifecycle retain honest actual-state readouts',()=>{for(const id of Object.keys(sources)){const f=integrated(id);f.open();const rate=f.panel.querySelector('[data-rate="0.25"]');assert(rate);rate.click();assert.equal(f.ui.simulationRate,.25);f.go.click();f.tick(.12);f.toggle(f.panel,false);assert.equal(f.ui.simulationRate,1);assert.equal(f.guide.open,false);assert.equal(f.read().enabled,false);assert.equal(f.primary.parentElement,f.dock);f.open();const before=f.snapshot();f.document.hidden=true;f.document.emit('visibilitychange');f.tick(.4);assert.equal(f.ui.simulationRate,1);f.document.hidden=false;f.document.emit('visibilitychange');f.event('pagehide');f.frame();f.event('pageshow');f.button('重新开始');f.finish();assert.equal(f.pending,0);assert.equal(f.read().completed,false);assert(before);}});
